ALTER TABLE public.stock_items DROP CONSTRAINT IF EXISTS stock_items_name_brand_category_type_unique;
DROP INDEX IF EXISTS public.stock_items_name_brand_category_type_unique;
DROP INDEX IF EXISTS public.stock_items_canonical_uniq;

DELETE FROM public.stock_items WHERE brand = 'sweatspot' AND category = 'producto_terminado';


CREATE UNIQUE INDEX stock_items_canonical_uniq
  ON public.stock_items (
    brand, category, lower(name),
    coalesce(product_type, ''),
    coalesce(logo, ''),
    coalesce(color, '')
  );